					return true
				}
				num[l]++
			}
			return false
		}
		if rf {
			if any_(0, r-1) {
				return true
			}
			if num[r] > 0 {
				num[r]--
				if dfs(idx+1, false, true) {
					return true
				}
				num[r]++
			}
			return false
		}
	}
	return false
}

func goFunc(idx int, rem int) {
	if idx == 10 {
		for i := 0; i < 10; i++ {
			num[i] = keep[i]
		}
		num[0] += rem
		if dfs(0, true, true) {
			ans++
		}
		return
	}
	for i := 0; i <= rem; i++ {
		keep[idx] = i
		goFunc(idx+1, rem-i)
	}
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	fmt.Fscan(reader, &l, &r)

	for l > 0 {
		lv = append(lv, int(l%10))
		l /= 10
	}
	for r > 0 {
		rv = append(rv, int(r%10))
		r /= 10
	}
	for len(lv) < len(rv) {
		lv = append(lv, 0)
	}
	for i, j := 0, len(lv)-1; i < j; i, j = i+1, j-1 {
		lv[i], lv[j] = lv[j], lv[i]
	}
	for i, j := 0, len(rv)-1; i < j; i, j = i+1, j-1 {
		rv[i], rv[j] = rv[j], rv[i]
	}

	goFunc(1, len(lv))
	fmt.Println(ans)
}
